try:
    from collections.abc import Iterable, Iterator
except ImportError:
    from collections import Iterable, Iterator
from abc import ABCMeta, abstractmethod
import six


class ThroughputData(object):

    """ThroughputData reflect the current status about the throughput during calculation process for a single device
    that is, it only keep the latest instantaneous throughput data and
    the accumulated throughput calculated result.
    the reason why not keep the historical throughput data is to save memory space
    to accept large log data stream and file
    """
    def __init__(self, device_id):
        self._device_id = device_id
        self._current = 0
        self._utc_time = ""
        self._result = None

    @classmethod
    def create(cls, device_id, throughput_value, timestamp, **kwargs):
        raise NotImplementedError()

    @property
    def device_id(self):
        return self._device_id

    @property
    def current(self):
        return self._current

    @current.setter
    def current(self, value):
        self._current = value

    @property
    def utc_time(self):
        return self._utc_time

    @utc_time.setter
    def utc_time(self, value):
        self._utc_time = value[0] if isinstance(value, tuple) else value.strip("('),")

    @property
    def result(self):
        return self._result

    def update(self, throughput_data):
        self._current = throughput_data.current
        self._utc_time = throughput_data.utc_time

    def reset(self):
        self._current = 0
        self._utc_time = ""
        self._result.reset()


class DeviceIterator(Iterator):
    def __init__(self, device_list):
        self._device_list = device_list
        self._index = 0

    def __next__(self):
        if self._index == len(self._device_list):
            raise StopIteration

        result = self._device_list[self._index]
        self._index += 1
        return result

    next = __next__


class ThroughputResult(Iterable):
    def __init__(self, device_id=None):
        self.device_id = device_id if device_id else None
        self.peak = 0
        self.average = 0.0
        self.minimum = 2147483647
        self.count = 0
        self.total = 0
        self.min_time_interval = 2147483647

    @property
    def device_id_key_name(self):
        return "device_id"

    def __iter__(self):
        return DeviceIterator([self])

    def to_dict(self):
        return {self.device_id_key_name: self.device_id, 'peak': self.peak, 'average': self.average,
                'minimum': self.minimum, 'count': self.count,
                'min_time_interval': self.min_time_interval}

    def __str__(self):
        return str(self.to_dict())

    def reset(self):
        self.peak = 0
        self.average = 0.0
        self.minimum = 2147483647
        self.count = 0
        self.total = 0
        self.min_time_interval = 2147483647


class MultipleDeviceThroughputResult(Iterable):
    def __init__(self, throughput_results):
        self._throughput_results = throughput_results

    def __iter__(self):
        return DeviceIterator(self._throughput_results)

    def reset(self):
        for result in self._throughput_results:
            result.reset()


class MbitsecThroughputResult(ThroughputResult):
    def __init__(self, throughput_result):
        super(MbitsecThroughputResult, self).__init__(throughput_result.device_id)

        self._original_result = throughput_result
        self.count = throughput_result.count
        if self.count:
            # as mail from Ramanunni, Vidhu A, counter update happens in 1024000 micro seconds
            # here round 3 point bits to avoid x.10239 and so on
            min_sec_time_interval = round(throughput_result.min_time_interval, 3)

            # mbps is 1000 times kbps 1000*1000 bytes than 1024 times in calculation
            unit_times = 8 / 1000.0 / 1000.0 / min_sec_time_interval
            self.peak = throughput_result.peak * unit_times
            self.average = throughput_result.average * unit_times
            self.minimum = throughput_result.minimum * unit_times
            self.total = throughput_result.total * unit_times
            self.min_time_interval = min_sec_time_interval
        else:
            self.peak = 0
            self.average = 0
            self.minimum = 0
            self.total = 0
            self.min_time_interval = 0

    @property
    def device_id_key_name(self):
        return self._original_result.device_id_key_name if self._original_result else super(
            (MbitsecThroughputResult, self).device_id_key_name)

    def to_dict(self):
        return {self.device_id_key_name: self.device_id, 'peak': self.peak, 'average': self.average,
                'minimum': self.minimum, 'count': self.count,
                'min_time_interval': self.min_time_interval}


@six.add_metaclass(ABCMeta)
class MultipleDevicesThroughputDataCollection(object):
    """
     MultipleDevicesThroughputDataCollection contains the current status about the throughputs
     during calculation process from multiple devices and
     responsible for common information shared in devices, e.g. minimal time interval, final integrated results
    """
    def __init__(self):
        self._throughput_data_dict = {}  # device id is the key
        self._current_throughput_data = None

    @abstractmethod
    def update(self, throughput_data):
        """pass"""

    @abstractmethod
    def reset(self):
        """pass"""

    def __getitem__(self, device_id):
        return self._throughput_data_dict.get(device_id)

    @property
    def throughput_data_dict(self):
        return self._throughput_data_dict

    @property
    def current_throughput_data(self):
        return self._current_throughput_data

    @property
    def min_time_interval(self):
        min_time_interval = 2147483647
        for _, throughput_data in self._throughput_data_dict.items():
            min_time_interval = throughput_data.result.min_time_interval \
                if throughput_data.result.min_time_interval < min_time_interval \
                else min_time_interval
        return min_time_interval

    def update_min_time_interval(self, throughput_data, value):
        throughput_data.result.min_time_interval = value

    @property
    def result(self):
        return MultipleDeviceThroughputResult([throughput_data.result
                                               for _, throughput_data in self._throughput_data_dict.items()])


class FixedDevicesThroughputDataCollection(MultipleDevicesThroughputDataCollection):
    def __init__(self, device_ids, throughput_data_factory):
        super(FixedDevicesThroughputDataCollection, self).__init__()
        for device_id in device_ids:
            self._throughput_data_dict[device_id] = throughput_data_factory.create(device_id)

    def update(self, throughput_data):
        if throughput_data.device_id not in self._throughput_data_dict:
            return False
        self._throughput_data_dict[throughput_data.device_id].update(throughput_data)
        self._current_throughput_data = self._throughput_data_dict[throughput_data.device_id]
        return True

    def reset(self):
        self._current_throughput_data = None
        for item in self._throughput_data_dict.values():
            item.reset()


class DynamicDevicesThroughputDataCollection(MultipleDevicesThroughputDataCollection):
    def __init__(self):
        super(DynamicDevicesThroughputDataCollection, self).__init__()

    def update(self, throughput_data):
        if throughput_data.device_id in self._throughput_data_dict:
            self._throughput_data_dict[throughput_data.device_id].update(throughput_data)
        else:
            self._throughput_data_dict[throughput_data.device_id] = throughput_data

        self._current_throughput_data = self._throughput_data_dict[throughput_data.device_id]
        return True

    def reset(self):
        self._current_throughput_data = None
        for item in self._throughput_data_dict.values():
            item.reset()
        self._throughput_data_dict.clear()
